This Terraform configuration creates an IPv6-enabled AWS VPC, attaches an egress-only internet gateway named `pike`, and adds an IPv6 default route so instances in the associated IPv6 subnet can initiate outbound internet connections while preventing unsolicited inbound IPv6 traffic. The egress-only internet gateway is tagged with `permissions`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "IPv4 CIDR block for the subnet."
  type        = string
  default     = "10.0.1.0/24"
}

